values.content:
=Analyze this lead email response:

Subject: {{ $('Set Email Details').item.json.Subject }}
From: {{ $('When Lead Reply Received').item.json.From }}
Body: {{ $('Set Email Details').item.json.emailBody }}

Return JSON only, no markdown or explanations.

parameters.jsCode:
// Parse the JSON text returned by OpenAI
const openAIResponse = $input.item.json.output[0].content[0].text;
const parsedData = JSON.parse(openAIResponse);

// Preserve original intent and create a normalized version for Switch matching
const intent = String(parsedData.intent ?? '').trim();
const intent_normalized = intent
  .toLowerCase()
  .replace(/\s+/g, ' ');

return {
  json: {
    // Original AI fields
    intent,
    intent_normalized,
    buying_stage: parsedData.buying_stage,
    sentiment: parsedData.sentiment,
    urgency: parsedData.urgency,
    summary: parsedData.summary,
    recommended_action: parsedData.recommended_action,
    follow_up_date: parsedData.follow_up_date,
    confidence_score: parsedData.confidence_score,

    // Original email fields
    emailBody: $input.item.json.emailBody,
    subject: $input.item.json.subject,
    senderEmail: $input.item.json.senderEmail,
    senderName: $input.item.json.senderName
  }
};

